mapper.select:
select count(id) from style_info where 1=1
and type_id = #{styleType}
and style_name ~ #{styleName}

select style_info.id as id, style_info.style_id as styleId, style_name as sldName, file_name as fileName, url as url, type_id as typeId, is_color as isColor, is_default as isDefault, upload_time as uploadTime, upload_person as uploader, style_map.servername as layerName from style_info left join ( select style_id as styleid,string_agg(map_server_info.server_name,',') as servername from server_style_info left join map_server_info on map_server_info.server_id = server_style_info.server_id group by server_style_info.style_id ) as style_map on style_map.styleid = style_info.id where 1=1
and type_id in (1,#{styleType})
and type_id in (#{styleType})
and style_name ~ #{styleName}
order by style_name ${pageInfo.sord}
order by upload_time desc
LIMIT #{pageInfo.pageSize} offset (${pageInfo.pageNum} - 1)*${pageInfo.pageSize}
order by upload_time desc

